INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (1, 'adductor-and-hamstring-stretch', 'Adductor & Hamstring Stretch', 'Focus on the areas that feel like they need the most stretch today.  Feel free to come back for more at the end!', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (2, 'adductor-cross', 'Adductor Cross', 'This one seems easy, but you might feel it later!  Make sure to work both sides evenly.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/adductor-crosses.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (3, 'banded-crab-walk', 'Banded Crab Walk', '', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (4, 'bench-press', 'Bench Press', 'If you don''t have a bench, you can do these on the ground (your elbow will stop at the ground).  Keep your lower back close to the bench or ground in a neutral position.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (5, 'bicep-curl', 'Bicep Curl', 'Try different grip and angle variations if these get too easy or boring: hammer curls, overhand grip, rotating curls (underhand up, overhand down), or side-angle curls.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (6, 'butterfly-bridge', 'Butterfly Bridge', 'If this is too easy, add weight on your hips.  If it''s too hard, bring your knees up and closer together while you build strength.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/butterfly-bridge.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (7, 'butterfly-sit-up', 'Butterfly Sit Up', 'If you can''t sit up all the way, make these crunches while you build strength.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (8, 'calf-raise', 'Calf Raise', 'As this becomes easier, place the ball of your foot on the edge of a step and let your heels sink down with each rep.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/calf-raise.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (9, 'calf-raise-and-curl', 'Calf Raise & Curl', 'Make these two distinct movements, fully completing each and checking your form before starting the next.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/calf-raise-and-curl.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (10, 'crunch', 'Crunch', 'Support your head in your hands if your neck gets tired in later reps.  Be careful not to pull your head forward if you do this - just rest it in your hands.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/crunch.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (11, 'curl-and-press', 'Curl & Press', 'Make these two distinct movements, fully completing each and checking your form before starting the next.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (12, 'curtsy-lunge', 'Curtsy Lunge', 'Your knee should come down to the ground right behind your opposite foot.  Take care to keep your torso upright.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/curtsy-lunge.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/curtsy-lunge-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (13, 'dead-bug', 'Dead Bug', 'Add one or two dumbbells in your hands to make this harder.  Keep your knee bent to make it easier.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/dead-bugs.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (14, 'diagonal-sit-up', 'Diagonal Sit Up', 'Work both sides evenly.  If you can''t sit up all the way, make these crunches while you build strength.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/diagonal-sit-ups.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (15, 'fire-hydrant', 'Fire Hydrant', 'Alignment of your resting leg is very important here - directly under your hip.  Don''t cut corners by shifting your hips to your resting side!', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/fire-hydrants.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (16, 'fire-hydrant-circle', 'Fire Hydrant Circle', 'Alignment of your resting leg is very important here - directly under your hip.  Don''t cut corners by shifting your hips to your resting side!', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/fire-hydrant-circles.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (17, 'flexor-lift', 'Flexor Lift', 'Resist the urge to rock your pelvis back to bring your leg higher.  Think about closing the angle between your torso and your femur without rounding your lower back.', NULL, 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/flexor-lifts-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (18, 'flexor-up-and-over', 'Flexor Up & Over', 'Resist the urge to rock your pelvis back to bring your leg higher.  Think about closing the angle between your torso and your femur without rounding your lower back.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (19, 'forward-lunge', 'Forward Lunge', 'Absorb the impact fluidly as you step forward and keep your balance as you push back.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/forward-lunge.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/forward-lunge-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (20, 'forward-lunge-with-twist', 'Forward Lunge w/ Twist', 'Don''t neglect the twist - pause in the lunge and twist as far as you can.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (21, 'forward-reach-squat', 'Forward Reach Squat', 'To make this easier, reach as you squat and retract your arms as you stand or limit your arms'' extension to as far as you can go.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/forward-reach-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (22, 'front-to-side-raise', 'Front to Side Raise', 'Make sure to move the weights straight up, then across, without turning the motion into a circle.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/front-to-side-raise.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (23, 'glute-arc', 'Glute Arc', 'Use your full range of motion here and go slow.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/glute-arcs.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (24, 'glute-bridge', 'Glute Bridge', 'Stack your knees directly over your ankles and don''t let them fall in or out.  Complete the full range of motion - push your hips as high as you can, keep them level, and pause at the top.  If this is too easy, place a weight on your hips.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/glute-bridge.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (25, 'goblet-squat', 'Goblet Squat', 'Hold the weight close to your chest and keep your shoulders upright throughout, with your toes facing forward.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/goblet-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (26, 'hamstring-bridge', 'Hamstring Bridge', 'Walk your feet out a step or two from glute bridge position to target your hamstrings.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/hamstring-bridge.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (27, 'heel-tap', 'Heel Tap', 'Make this harder by walking your feet closer together and further away from you.  Make it easier by doing the opposite.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/heel-taps.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (28, 'hip-circle', 'Hip Circle', 'Move in the range of motion that feels good and productive for you today.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/hip-circles.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (29, 'hip-dip-plank', 'Hip Dip Plank', 'If you''re still working on your forearm plank, start from a knee plank and lift one knee off the ground at a time, alternating, skipping the dip until you can hold a plank for 10+ seconds.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/hip-dip-plank.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (30, 'hip-rocker', 'Hip Rocker', 'To make this harder, add a weight on your hips.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/hip-rockers.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (31, 'ice-skater', 'Ice Skater', 'Slow this down as much as you need to to keep your balance.  Speed it up to challenge yourself.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/ice-skaters.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (32, 'jump-squat', 'Jump Squat', 'Make your landing soft and fluid to practice absorbing impact.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/jump-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (33, 'jumping-jack', 'Jumping Jack', 'Don''t overthink it; just get moving and warm up.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/jumping-jacks.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (34, 'knee-assist-plank', 'Knee Assist Plank', 'Make this harder by holding a forearm plank for a few seconds and returning to knee assist to build more plank stamina.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/knee-assist-plank.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (35, 'knee-up', 'Knee Up', '', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (36, 'lat-pull-over', 'Lat Pull Over', 'You should feel this in your back and sides.  Make sure your elbows and wrists stay straight so that you aren''t using your arms instead.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/lat-pull-over.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (37, 'lateral-pogo', 'Lateral Pogo', 'Keep this motion as small as you need to to maintain control.  Turn it into a pogo if the lateral movement is too much.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/lateral-pogos.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (38, 'mountain-climber', 'Mountain Climber', 'Slow this down if the fast motion is uncomfortable.  If this gets too easy, add a push up every few reps.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/mountain-climber.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (39, 'nordic-and-curl', 'Nordic & Curl', 'The eccentric contraction of your quads here can create a lot of soreness.  Ease in if you''re new to these!', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/nordic-and-curl.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (40, 'oblique-crunch', 'Oblique Crunch', 'This is a precise movement - make sure you''re engaging the space between your hip and your ribs to lift.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/oblique-crunch.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (41, 'pike-push-up', 'Pike Push Up', 'The depth of your push up will increase as you build strength in this exercise.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/pike-push-up.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (42, 'plank-hold', 'Plank Hold', 'Rest on your hands or forearms as you choose.  Work from either your knees or toes, or alternate between them as you build strength.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (43, 'plank-pike', 'Plank Pike', 'Do this on your forearms or hands as you prefer.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/plank-pike.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (44, 'plank-toe-tap', 'Plank Toe Tap', 'If this is too hard, practice holding a plank or just lifting each foot.  Use your hands or forearms as you prefer.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/plank-toe-taps.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (45, 'plank-twist', 'Plank Twist', 'When this gets too easy, add a push up in between twists.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/plank-twist.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (46, 'pogo', 'Pogo', 'Keep this motion as small as you need to to maintain control.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/pogos.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (47, 'pull-up', 'Pull Up', 'Use extra hang time and slow descents to build strength for more reps.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (48, 'push-up', 'Push Up', 'Take any variant you want here.  Knees, plank, knee assist, jack - anything you want!', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/push-up.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (49, 'rdl-row-kickback', 'RDL - Row - Kickback', 'Make these three distinct movements, fully completing each and checking your form before starting the next.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/rdl-row-kickback.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (50, 'rdl-and-row', 'RDL & Row', 'Make these two distinct movements, fully completing each and checking your form before starting the next.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/rdl-and-row.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (51, 'rest', 'Rest', NULL, NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (52, 'reverse-crunch', 'Reverse Crunch', 'Make sure to use your core strength here instead of relying on momentum.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/reverse-crunch.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (53, 'reverse-fly', 'Reverse Fly', 'Go slowly and stop the weight fully at the top and bottom of the movement to ensure you aren''t relying on momentum to help you.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/reverse-fly.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/reverse-fly-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (54, 'reverse-lunge', 'Reverse Lunge', 'Step back slowly, keeping your balance throughout the motion.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (55, 'reverse-lunge-tap', 'Reverse Lunge Tap', 'This is a balance and control exercise - move slowly and pause any time you start to wobble.  When this gets too easy, increase your range of motion and add hand weights.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/reverse-lunge-tap.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/reverse-lunge-taps-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (56, 'romanian-dead-lift', 'Romanian Dead Lift', 'Focus on hinging at the hip with a soft bend in your knee - imagine making a 7 with your body.  Move with control and build up your weight slowly.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/romanian-dead-lift.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (57, 'row', 'Row', 'Make sure to lower the weight slowly and pull it up close to your ribs.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/row.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (58, 'row-and-kickback', 'Row & Kickback', 'This will probably feel like an easy row and a hard kickback.  Work to straighten out the elbow on the kickback and go slow on the row.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/row-and-kickback.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (59, 'runner-hop', 'Runner Hop', '', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (60, 'russian-twist', 'Russian Twist', 'Increase your range of motion, add weight, and extend your legs as you get stronger.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/russian-twist.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (61, 'shoulder-press', 'Shoulder Press', 'Keep your elbows at a 45-degree angle to avoid excess shoulder strain.  Bring them closer together if you need to.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (62, 'side-lunge', 'Side Lunge', 'Pause to find your balance on each step out and back in.  Take a smaller step to make this easier and a bigger step to make it harder.', NULL, 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/side-lunge-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (63, 'side-lunge-with-balance-press', 'Side Lunge w/ Balance Press', 'Move with control and pause to find your balance with each step.  Make this two distinct and controlled movements.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (64, 'side-lying-leg-lift', 'Side Lying Leg Lift', 'To make this easier, rest your hips on the ground instead of lifting from your knee.  To make it harder, lift from your bottom foot instead of knee.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/side-lying-leg-lift.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (65, 'single-arm-row', 'Single Arm Row', 'Pull the weight all the way to your ribs and pause briefly at the top of the motion.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-arm-row.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-arm-row-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (66, 'single-arm-row-with-top-hold', 'Single Arm Row w/ Top Hold', 'Hold the weight right by your ribs and keep your back flat.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (67, 'single-leg-forward-hop', 'Single Leg Forward Hop', '', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-leg-forward-hops.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (68, 'single-leg-glute-bridge', 'Single Leg Glute Bridge', 'Stack your knees directly over your ankles and don''t let them fall in or out.  Complete the full range of motion - push your hips as high as you can, keep them level, and pause at the top.  If this is too easy, place a weight on your hips.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-leg-glute-bridge.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (69, 'single-leg-pogo', 'Single Leg Pogo', 'If this is too hard, start on both legs and add a hop or two on one leg every once in a while.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-leg-pogos.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (70, 'single-leg-rdl', 'Single Leg RDL', 'Keep your hips and shoulders square as you hinge.  Hold the weight in either or both hands as you find most effective.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/single-leg-rdl.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (71, 'skull-crusher', 'Skull Crusher', 'Hinge at your elbow, extending and lowering slowly and with control.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/skull-crusher.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (72, 'split-squat', 'Split Squat', 'Your front leg is doing the work here and your back leg is for stability.  Keep your knee aligned between your hip and ankle.  Make sure this is a squatting motion more than a hip hinging motion.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/split-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (73, 'squat-and-press', 'Squat & Press', 'Make these two distinct movements without relying on momentum to move between them.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/squat-and-press.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (74, 'squat-twist', 'Squat Twist', 'Squat as deeply or shallowly as feels right for you today.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/squat-twist.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (75, 'standing-abduction', 'Standing Abduction', 'Keep your balance as you rotate your knee out, using your glutes to open your hip.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/standing-abduction.mp4', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/standing-abduction-alt.mp4');
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (76, 'standing-cat-cow', 'Standing Cat/Cow', 'Practice your range of motion and control over different hip angles.', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (77, 'standing-lateral-leg-lift', 'Standing Lateral Leg Lift', '', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/standing-lateral-leg-lift.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (78, 'static-lunge', 'Static Lunge', 'Keep your knees aligned: the front knee stays over your toes without falling in or out, and the back knee goes straight to the ground.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/static-lunge.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (79, 'suitcase-squat', 'Suitcase Squat', 'Keep your shoulders upright and your weight in your heels as you squat down.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/suitcase-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (80, 'sumo-goblet-squat', 'Sumo Goblet Squat', 'Engage your glutes as you stand and keep your shoulders upright throughout.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/sumo-goblet-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (81, 'sumo-squat', 'Sumo Squat', 'Point your toes out at a 45-degree angle from your body.  Engage your glutes as you stand and keep your shoulders upright throughout.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/sumo-squat.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (82, 'sumo-squat-curl-press', 'Sumo Squat/Curl/Press', 'Point your toes out at a 45-degree angle.  Make these three distinct movements without relying on momentum to move between them.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/sumo-squat-curl-press.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (83, 'superman-pull-down', 'Superman Pull Down', '', NULL, NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (84, 'superman-sweep', 'Superman Sweep', 'Work in the range of motion you can, focusing on lifting your shoulders higher and reaching further back as you get stronger.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/superman-sweep.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (85, 'tabletop-cat-cow', 'Tabletop Cat/Cow', 'Explore your range of motion in your hip angle and upper back.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/tabletop-cat-cow.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (86, 'to-the-chin-lift', 'To-the-Chin Lift', 'Make sure to keep your elbow elevated to shoulder height.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/to-the-chin-lift.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (87, 'toe-tap', 'Toe Tap', 'Don''t worry if you can''t reach your toes - the point is to add the dynamic movement of the crunch on top of the static hold of keeping your legs up.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/toe-taps.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (88, 'unilateral-calf-raise-and-curl-hold', 'Unilateral Calf Raise & Curl Hold', 'Use the toes of your resting leg to help you balance.  If this is too hard, drop the weights for the calf raise and do curls separately.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/unilateral-calf-raise-and-curl-hold.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (89, 'weighted-bird-dog', 'Weighted Bird Dog', 'Drop the weight if this is too hard on your shoulders.  Extend and contract through as much range of motion as you can.', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/weighted-bird-dogs.mp4', NULL);
INSERT INTO exercises (id, slug, name, tips, video, video_alternating) VALUES (90, 'y-scaption', 'Y Scaption', 'If this bothers your shoulders, sub with a fly (arms straight to your sides) or a W scaption (elbows bent, arms to your sides).', 'https://6a94koge7mtrmdjd.public.blob.vercel-storage.com/exercises/y-scaption.mp4', NULL);
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (1, 'leg-day', 'Leg Day', 'moderate', 'Key lower body exercises with unilateral focus.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (2, 'paul-upper-body', 'Paul Upper Body', 'moderate', 'Key upper body exercises - push, pull, and press for chest, shoulders, back, and biceps.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (3, 'rider-alternating-supersets', 'Rider Alternating Supersets', 'easier', 'An approachable take on unilateral work for a lighter day or starting out.  Superset format, each with a compound movement and an opposing alternating isolation.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (4, 'rider-build-1', 'Rider Build 1', 'harder', 'Focused training to isolate and build key muscles.  Superset format, each with a compound movement and an isolation that build the same muscles.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (5, 'rider-build-2', 'Rider Build 2', 'harder', 'Focused training to isolate and build key muscles.  Superset format, each with a compound movement and an isolation that build the same muscles.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (6, 'rider-mini-circuits-1', 'Rider Mini Circuits 1', 'easier', 'Short circuits of three exercises, three rounds each.  Approachable compound movements for lighter days or starting out.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (7, 'rider-mini-circuits-2', 'Rider Mini Circuits 2', 'easier', 'Short circuits of three exercises, three rounds each.  Approachable compound movements for lighter days or starting out.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (8, 'rider-single-leg-sandwiches-1', 'Rider Single Leg Sandwiches 1', 'moderate', 'The sandwich format is an especially time-efficient way to get focused unilateral work in.  Compound, left-right-left-right, compound.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (9, 'rider-single-leg-sandwiches-2', 'Rider Single Leg Sandwiches 2', 'moderate', 'The sandwich format is an especially time-efficient way to get focused unilateral work in.  Each set is compound, left-right-left-right, compound.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (10, 'rider-symmetry-and-balance-1', 'Rider Symmetry & Balance 1', 'moderate', 'Isolated unilateral work to enforce symmetrical strength, proprioception, and balance.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (11, 'rider-symmetry-and-balance-2', 'Rider Symmetry & Balance 2', 'moderate', 'Isolated unilateral work to enforce symmetrical strength, proprioception, and balance.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (12, 'runner-mini-circuits-1', 'Runner Mini Circuits 1', 'easier', 'Short circuits of three exercises, three rounds each.  Approachable compound movements for lighter days or starting out.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (13, 'runner-single-leg-sandwiches-1', 'Single Leg Sandwiches 1', 'moderate', 'The sandwich format is an especially time-efficient way to get focused unilateral work in.  Each set is compound, left-right-left-right, compound.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (14, 'runner-single-leg-sandwiches-2', 'Single Leg Sandwiches 2', 'moderate', 'The sandwich format is an especially time-efficient way to get focused unilateral work in.  Each set is compound, left-right-left-right, compound.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (15, 'runner-unilateral-mini-circuits-3c3r', 'Runner Unilateral Mini Circuits 3c3r', 'moderate', 'Unilateral work in a mini-circuit format.  Three circuits, three rounds each.');
INSERT INTO workouts (id, slug, name, difficulty, description) VALUES (16, 'runner-unilateral-mini-circuits-4c2r', 'Runner Unilateral Mini Circuits 4c2r', 'moderate', 'Unilateral work in a mini-circuit format.  Four circuits, two rounds each.');
